import{_ as s,o as n,c as e,a6 as i}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"判断ガイド: 最適化すべきか・リファクタリングすべきか","description":"","frontmatter":{"title":"判断ガイド: 最適化すべきか・リファクタリングすべきか","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"どちらも「機能が増えない作業」への投資判断です。共通原則: 痛みの証拠(計測・履歴)を要求し、投資対効果で決める。 トレードオフ: 速度 ⇔ 可読性・移植性・開発速度。「最適化した状態」は保守コストが高いので、目標を満たしたら止める"}},"headers":[],"relativePath":"design/decisions/optimize-or-refactor.md","filePath":"design/decisions/optimize-or-refactor.md"}'),p={name:"design/decisions/optimize-or-refactor.md"};function t(l,a,o,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="判断ガイド-最適化すべきか・リファクタリングすべきか" tabindex="-1">判断ガイド: 最適化すべきか・リファクタリングすべきか <a class="header-anchor" href="#判断ガイド-最適化すべきか・リファクタリングすべきか" aria-label="Permalink to &quot;判断ガイド: 最適化すべきか・リファクタリングすべきか&quot;">​</a></h1><p>どちらも「機能が増えない作業」への投資判断です。共通原則: <strong>痛みの証拠(計測・履歴)を要求し、投資対効果で決める</strong>。</p><h2 id="最適化すべきか" tabindex="-1">最適化すべきか <a class="header-anchor" href="#最適化すべきか" aria-label="Permalink to &quot;最適化すべきか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. 性能目標(フレーム時間・メモリ・ロード時間)を数字で言えるか?</span></span>
<span class="line"><span>    → 言えない ──&gt; まず目標設定(目標なき最適化は終わらない)</span></span>
<span class="line"><span>Q2. 目標を満たしていないか?(実機・Shipping相当構成で計測 → [ビルド構成](../08_build_system/04_build_configurations.md))</span></span>
<span class="line"><span>    → 満たしている ──&gt; 最適化しない(浮いた時間で機能・品質へ)</span></span>
<span class="line"><span>Q3. プロファイラでボトルネックを特定したか?</span></span>
<span class="line"><span>    → していない ──&gt; 計測が先。「たぶんここが遅い」は大抵外れる</span></span>
<span class="line"><span>Q4. ボトルネックへの対策を、コスト順に検討:</span></span>
<span class="line"><span>    (1) 無駄の削除(呼ばなくていい処理、空Update、重複計算)← まずここ。設計を汚さない</span></span>
<span class="line"><span>    (2) アルゴリズム・データ構造(O(N²)→[空間分割](../04_game_patterns/optimization_patterns.md)、[キャッシュ局所性](../07_memory_and_runtime/05_cache_locality_aos_soa.md))</span></span>
<span class="line"><span>    (3) 構造の変更(プール、SoA、並列化)← 可読性を払う。効果を再計測で確認</span></span>
<span class="line"><span>    (4) 低レベル(SIMD手書き、アセンブリ確認)← 最後の手段</span></span>
<span class="line"><span>Q5. 例外 — 最初から設計に織り込むもの:</span></span>
<span class="line"><span>    データレイアウト・フレーム構造・アセットストリーミングなど「後から変えられない」性能決定</span></span>
<span class="line"><span>    ([早すぎる最適化](../01_design_basics/09_yagni_kiss_dry.md)の「例外」節)</span></span></code></pre></div><ul><li>トレードオフ: 速度 ⇔ 可読性・移植性・開発速度。<strong>「最適化した状態」は保守コストが高い</strong>ので、目標を満たしたら止める</li><li>罠: デバッグビルドで計測(<a href="/study/runtime/cpp-internals/optimization-and-ub.html">最適化なしの計測は無意味</a>)/計測コードが最適化で消える/平均だけ見てスパイク(GC・ロード)を見逃す</li></ul><h2 id="リファクタリングすべきか" tabindex="-1">リファクタリングすべきか <a class="header-anchor" href="#リファクタリングすべきか" aria-label="Permalink to &quot;リファクタリングすべきか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. そのコードを近々(今スプリント〜数週間)変更する予定があるか?</span></span>
<span class="line"><span>    → ない ──&gt; しない(触らないコードの負債は利息ゼロ → [技術的負債](../01_design_basics/10_tech_debt_and_refactoring.md))</span></span>
<span class="line"><span>    → ある ──&gt; Q2へ</span></span>
<span class="line"><span>Q2. 現在の構造が、その変更を高くしているか?(見積りの差で考える:</span></span>
<span class="line"><span>    「今の構造で2日、直せば半日+リファクタ1日」なら、2回目の変更から黒字)</span></span>
<span class="line"><span>    → 高くしていない ──&gt; しない(綺麗さのためのリファクタは投資でなく趣味)</span></span>
<span class="line"><span>    → 高くしている ──&gt; Q3へ</span></span>
<span class="line"><span>Q3. 振る舞いを固定する手段(テスト、確認手順)はあるか?</span></span>
<span class="line"><span>    → ない ──&gt; 先に作る(なしでのリファクタは改悪リスクが利益を食う)</span></span>
<span class="line"><span>Q4. 実行: 機能追加と混ぜず、小さく、動かしたまま</span></span>
<span class="line"><span>    (準備のリファクタ → 機能追加 → 掃除のリファクタ、を別コミットで)</span></span></code></pre></div><ul><li><strong>最良のタイミングは「これから触る場所を、触るついでに」</strong>(準備のリファクタリング)。専用の「リファクタリング週間」より、日々の変更に混ぜる方が安全で確実</li><li>リリース直前・振る舞い固定手段なし・触る予定なし、の3条件はどれか1つでも「今はしない」</li></ul><h2 id="_2つの判断の関係" tabindex="-1">2つの判断の関係 <a class="header-anchor" href="#_2つの判断の関係" aria-label="Permalink to &quot;2つの判断の関係&quot;">​</a></h2><ul><li>最適化とリファクタリングは<strong>逆方向の変形</strong>になりがち(最適化は構造を特殊化し、リファクタリングは一般化する)。同時にやらない</li><li>ただし「変更しやすい構造」は最適化の前提でもある(ボトルネックを差し替えられる構造 → <a href="/study/design/foundations/quality-attributes.html">品質特性の衝突</a>)——順序は「リファクタで変更可能に → 計測 → 局所を最適化」</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>最適化の前に必要な2つのもの(目標・計測)がない場合、何が起きますか。</li><li>「触らないコードの負債は利息ゼロ」の意味と、その帰結は?</li><li>最適化とリファクタリングを同時にやるべきでない理由は?</li></ol><hr><p>前: <a href="/study/design/decisions/cpp-choices.html">C++の選択</a> | <a href="/study/design/decisions/">カテゴリ目次</a> | 次: <a href="/study/design/decisions/exercises.html">演習</a></p>`,14)])])}const _=s(p,[["render",t]]);export{u as __pageData,_ as default};
